begin;
insert into public.hr_permissions(code,name,module) values ('support.create','Create support conversations','Support'),('support.manage','Manage support conversations','Support') on conflict(code) do update set name=excluded.name,module=excluded.module;
insert into public.hr_role_permissions(role_id,permission_id) select r.id,p.id from public.hr_roles r cross join public.hr_permissions p where p.code='support.create' on conflict do nothing;
insert into public.hr_role_permissions(role_id,permission_id) select r.id,p.id from public.hr_roles r join public.hr_permissions p on p.code='support.manage' where lower(r.name)='admin' on conflict do nothing;
create table if not exists public.support_tickets(id bigint generated by default as identity primary key,clinic_id bigint not null default public.current_clinic_id() references public.clinics(id) on delete cascade,branch_id bigint default public.current_branch_id() references public.branches(id) on delete set null,requester_staff_id bigint not null default public.current_staff_id() references public.staff(id) on delete cascade,assigned_staff_id bigint references public.staff(id) on delete set null,subject text not null check(char_length(trim(subject)) between 3 and 180),category text not null default 'question' check(category in('question','problem','suggestion')),priority text not null default 'normal' check(priority in('low','normal','high','urgent')),status text not null default 'open' check(status in('open','in_progress','resolved','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.support_messages(id bigint generated by default as identity primary key,ticket_id bigint not null references public.support_tickets(id) on delete cascade,sender_staff_id bigint not null default public.current_staff_id() references public.staff(id) on delete cascade,body text not null check(char_length(trim(body)) between 1 and 4000),created_at timestamptz not null default now(),read_at timestamptz);
create index if not exists support_tickets_clinic_updated_idx on public.support_tickets(clinic_id,updated_at desc);create index if not exists support_messages_ticket_created_idx on public.support_messages(ticket_id,created_at);
alter table public.support_tickets enable row level security;alter table public.support_messages enable row level security;
drop policy if exists support_tickets_read on public.support_tickets;create policy support_tickets_read on public.support_tickets for select to authenticated using(clinic_id=public.current_clinic_id() and(requester_staff_id=public.current_staff_id() or public.has_hr_permission('support.manage')));
drop policy if exists support_tickets_create on public.support_tickets;create policy support_tickets_create on public.support_tickets for insert to authenticated with check(clinic_id=public.current_clinic_id() and requester_staff_id=public.current_staff_id() and public.has_hr_permission('support.create'));
drop policy if exists support_tickets_manage on public.support_tickets;create policy support_tickets_manage on public.support_tickets for update to authenticated using(clinic_id=public.current_clinic_id() and public.has_hr_permission('support.manage')) with check(clinic_id=public.current_clinic_id() and public.has_hr_permission('support.manage'));
drop policy if exists support_messages_read on public.support_messages;create policy support_messages_read on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and t.clinic_id=public.current_clinic_id() and(t.requester_staff_id=public.current_staff_id() or public.has_hr_permission('support.manage'))));
drop policy if exists support_messages_create on public.support_messages;create policy support_messages_create on public.support_messages for insert to authenticated with check(sender_staff_id=public.current_staff_id() and exists(select 1 from public.support_tickets t where t.id=ticket_id and t.clinic_id=public.current_clinic_id() and t.status<>'closed' and(t.requester_staff_id=public.current_staff_id() or public.has_hr_permission('support.manage'))));
create or replace function public.support_message_activity() returns trigger language plpgsql security definer set search_path=public as $$declare t support_tickets%rowtype;begin select * into t from support_tickets where id=new.ticket_id;update support_tickets set updated_at=now(),status=case when status='resolved' then 'in_progress' else status end where id=new.ticket_id;if new.sender_staff_id=t.requester_staff_id then insert into enterprise_notifications(clinic_id,branch_id,recipient_staff_id,title,message,type,href) select t.clinic_id,t.branch_id,sr.staff_id,'طلب دعم جديد','رسالة جديدة — '||t.subject,'support','/support' from hr_staff_roles sr join hr_role_permissions rp on rp.role_id=sr.role_id join hr_permissions p on p.id=rp.permission_id join staff s on s.id=sr.staff_id and s.clinic_id=t.clinic_id and s.is_active where p.code='support.manage' and sr.staff_id<>new.sender_staff_id;else insert into enterprise_notifications(clinic_id,branch_id,recipient_staff_id,title,message,type,href)values(t.clinic_id,t.branch_id,t.requester_staff_id,'رد جديد من الدعم','تم الرد على: '||t.subject,'support','/support');end if;return new;end$$;
drop trigger if exists support_message_activity_trigger on public.support_messages;create trigger support_message_activity_trigger after insert on public.support_messages for each row execute function public.support_message_activity();
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='support_tickets')then alter publication supabase_realtime add table public.support_tickets;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='support_messages')then alter publication supabase_realtime add table public.support_messages;end if;end$$;
commit;
